/* prog54_topo_sort – reproduced from the obfuscated binary
 *
 * The original binary implements a tiny topological‑sort utility for
 * directed graphs with at most 8 vertices.  It expects the command line
 * to contain an even number of arguments after the program name:
 *
 *   prog54_topo_sort  N  M  u1 v1  u2 v2  …  uM vM
 *
 *   N – number of vertices (0 ≤ N ≤ 8)
 *   M – number of directed edges (0 ≤ M ≤ 8)
 *   ui vi – an edge from ui to vi (0 ≤ ui,vi < N)
 *
 * If the input does not satisfy these constraints the program prints
 * "INVALID_INPUT" and exits with status 1.
 *
 * If the graph contains a directed cycle the program prints "CYCLE"
 * and exits with status 1.
 *
 * Otherwise it prints a topological ordering of the vertices.  The
 * ordering is produced with a simple stack (LIFO) – the same order as
 * the original binary – and each vertex is printed as a decimal number
 * followed by a single space.  After the last vertex a newline is
 * printed and the program exits with status 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8

int main(int argc, char *argv[])
{
    /* The original code required an even number of arguments after the
       program name (i.e. (argc‑1) must be even).  This is equivalent to
       having at least three arguments (program name, N, M) and then an
       even number of edge specifications. */
    if (argc < 3 || ((argc - 1) & 1)) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* Parse N and M */
    int N = strtol(argv[1], NULL, 10);
    int M = strtol(argv[2], NULL, 10);

    if (N < 0 || N > MAXV || M < 0 || M > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* The remaining arguments must be exactly 2·M numbers. */
    if (argc != 3 + 2 * M) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* Graph representation */
    int indegree[MAXV] = {0};
    bool adj[MAXV][MAXV] = {{false}};
    bool done[MAXV] = {false};

    /* Read edges */
    for (int i = 0; i < M; ++i) {
        int u = strtol(argv[3 + 2 * i], NULL, 10);
        int v = strtol(argv[3 + 2 * i + 1], NULL, 10);

        if (u < 0 || u >= N || v < 0 || v >= N) {
            puts("INVALID_INPUT");
            return 1;
        }

        /* Store edge u → v (ignore duplicates) */
        if (!adj[u][v]) {
            adj[u][v] = true;
            indegree[v]++;          /* increase indegree of the target */
        }
    }

    /* Stack for vertices with indegree 0 */
    int stack[MAXV];
    int sp = 0;                     /* stack pointer */

    for (int v = 0; v < N; ++v) {
        if (indegree[v] == 0) {
            stack[sp++] = v;
        }
    }

    int printed = 0;

    while (sp > 0) {
        int cur = stack[--sp];      /* pop (LIFO) */
        if (done[cur]) continue;   /* safety check */

        printf("%d ", cur);
        printed++;
        done[cur] = true;

        /* Decrease indegree of all neighbours */
        for (int nxt = 0; nxt < N; ++nxt) {
            if (adj[cur][nxt]) {
                indegree[nxt]--;
                if (indegree[nxt] == 0) {
                    stack[sp++] = nxt;
                }
            }
        }
    }

    if (printed < N) {
        puts("CYCLE");
        return 1;
    }

    putchar('\n');
    return 0;
}
